User: A square is divided into nine smaller squares of equal area. The center square is then divided into nine smaller squares of equal area and the pattern continues indefinitely. What fractional part of the figure is shaded? [asy]
import olympiad; size(150); defaultpen(linewidth(0.8)); dotfactor=4;
void drawSquares(int n){

draw((n,n)--(n,-n)--(-n,-n)--(-n,n)--cycle);

fill((-n,n)--(-1/3*n,n)--(-1/3*n,1/3*n)--(-n,1/3*n)--cycle);

fill((-n,-n)--(-1/3*n,-n)--(-1/3*n,-1/3*n)--(-n,-1/3*n)--cycle);

fill((n,-n)--(1/3*n,-n)--(1/3*n,-1/3*n)--(n,-1/3*n)--cycle);

fill((n,n)--(1/3*n,n)--(1/3*n,1/3*n)--(n,1/3*n)--cycle);
}

drawSquares(81); drawSquares(27); drawSquares(9); drawSquares(3); drawSquares(1);
[/asy]
